pid_t wpid;
int status;
pid_t child_pid = fork();

if (child_pid == 0) {
    // Child: do work and terminate
    // Parent receives resources upon wait()
    exit(42);
}

if (child_pid > 0) {
    // Parent suspends execution
    wpid = wait(&status);

    if (wpid != -1 && wpid == child_pid) {
        // Successful termination capture
        if (WIFEXITED(status)) {
            // Retrieve exit code:
            int exit_code = WEXITSTATUS(status);
        }
    }
}
